@@ -286,6 +286,27 @@ function flatSize(array: unknown[], depth: number): number {
  */
 const STRINGIFIES_ELEMENTS = new Set(['join', 'toSorted']);

+/**
+ * Array methods that compare each element against the argument. A string
+ * element is compared character by character, so the work is its content,
+ * not one unit per element.
+ */
+const COMPARES_ELEMENTS = new Set(['includes', 'indexOf', 'lastIndexOf']);
+
+/**
+ * Work for comparing each element of an array against one argument: a string
+ * element's length, one for any other element. Stops past the budget, which
+ * the caller's charge would reject anyway.
+ */
+function elementContent(receiver: unknown[]): number {
+	let weight = 0;
+	for (const element of receiver) {
+		weight += typeof element === 'string' ? element.length : 1;
+		if (weight > MAX_WORK) break;
+	}
+	return weight;
+}
+
 /**
  * Hands off to the engine unless every element is a primitive. O(n) over a
  * receiver the size cap already limits, and runs before anything is
@@ -389,6 +410,7 @@ function evalCall(node: Extract<SimpleNode, { kind: 'call' }>, env: Env): unknow
 	if (isArray(receiver)) {
 		if (STRINGIFIES_ELEMENTS.has(node.method)) assertPrimitiveElements(receiver);
 		if (node.method === 'concat') assertConcatWeight(receiver, args);
+		if (COMPARES_ELEMENTS.has(node.method)) env.charge(elementContent(receiver));
 	}
 	env.charge(preflightSize(receiver, node.method, args));

